-- =============================================================================
-- Activations for clearance_usl, in dependency order: parents (market_allergen,
-- fda_recall, fsa_alert, product) before the tables whose foreign keys point
-- at them. Every activation reads the raw REST tables, with COALESCE on every
-- NOT NULL column. Firm street addresses are never selected.
-- product and declared_allergen are GENERATED by gateway/sqlgen.py from the
-- intake manifest and DESCRIBE output (Day-0 gate set: 3 SKUs). Optional OFF
-- fields missing from a record are emitted as CAST(NULL AS STRING).
-- Ops tables (market_allergen, extracted_allergen, recall_product_link,
-- decision) filter out the "__schema__" sentinel row.
-- =============================================================================

ACTIVATE USL TABLE lightning.metastore.clearshelf.clearance_usl.market_allergen AS
SELECT COALESCE(d.market_code, '') AS market_code, COALESCE(d.market, '') AS market, COALESCE(d.allergen, '') AS allergen,
       d.display_name, d.statute, d.edition, d.citation_url
FROM clearshelf_ops.market_allergens LATERAL VIEW explode(data) x AS d
WHERE d.market_code <> '__schema__';

ACTIVATE USL TABLE lightning.metastore.clearshelf.clearance_usl.fda_recall AS
SELECT COALESCE(r.recall_number, '') AS recall_number,
       COALESCE(concat(substr(r.report_date, 1, 4), '-', substr(r.report_date, 5, 2), '-', substr(r.report_date, 7, 2)), '') AS report_date,
       r.classification, r.status, r.recalling_firm AS firm, r.distribution_pattern AS distribution,
       r.product_description, r.reason_for_recall AS reason, r.code_info
FROM clearshelf_fda.enforcement_undeclared LATERAL VIEW explode(results) x AS r;

ACTIVATE USL TABLE lightning.metastore.clearshelf.clearance_usl.fsa_alert AS
SELECT COALESCE(a.notation, '') AS notation, COALESCE(substr(a.created, 1, 10), '') AS created,
       a.title, a.reportingBusiness.commonName AS business, a.alertURL AS alert_url
FROM clearshelf_fsa.allergy_alerts LATERAL VIEW explode(items) x AS a;

-- GENERATED by gateway/sqlgen.py
ACTIVATE USL TABLE lightning.metastore.clearshelf.clearance_usl.product AS
SELECT '0816929000119' AS gtin, product.product_name AS product_name, CAST(NULL AS STRING) AS brand, product.lang AS lang, CAST(NULL AS STRING) AS ingredients_text, CAST(NULL AS STRING) AS ingredients_text_en, array_join(product.labels_tags, ',') AS labels, CASE WHEN array_contains(product.labels_tags, 'en:vegan') THEN 'yes' ELSE 'no' END AS vegan_claim, CAST(product.last_modified_t AS STRING) AS last_modified, 'https://world.openfoodfacts.org/product/0816929000119' AS source_url FROM clearshelf_off.off_0816929000119
UNION ALL
SELECT '4056489125846' AS gtin, product.product_name AS product_name, product.brands AS brand, product.lang AS lang, product.ingredients_text AS ingredients_text, CAST(NULL AS STRING) AS ingredients_text_en, array_join(product.labels_tags, ',') AS labels, CASE WHEN array_contains(product.labels_tags, 'en:vegan') THEN 'yes' ELSE 'no' END AS vegan_claim, CAST(product.last_modified_t AS STRING) AS last_modified, 'https://world.openfoodfacts.org/product/4056489125846' AS source_url FROM clearshelf_off.off_4056489125846
UNION ALL
SELECT '5000254020408' AS gtin, product.product_name AS product_name, product.brands AS brand, product.lang AS lang, product.ingredients_text AS ingredients_text, product.ingredients_text_en AS ingredients_text_en, array_join(product.labels_tags, ',') AS labels, CASE WHEN array_contains(product.labels_tags, 'en:vegan') THEN 'yes' ELSE 'no' END AS vegan_claim, CAST(product.last_modified_t AS STRING) AS last_modified, 'https://world.openfoodfacts.org/product/5000254020408' AS source_url FROM clearshelf_off.off_5000254020408;

